FROM chapter_content cc
JOIN chapters ch ON ch.id = cc.chapter_id
JOIN subjects s ON s.id = ch.subject_id
JOIN classes c ON c.id = s.class_id
WHERE l.chapter_content_id = cc.id
  AND c.name = 'CLASS 3'
  AND ch.title = 'Chapter 4 — AI RISE'
  AND cc.title = 'When I Grow Up';

